import { useState } from 'react';
import { Search, MapPin, List, Map as MapIcon, Star, ChevronRight } from 'lucide-react';
import { Navbar } from '../components/common/Navbar';
import { PageTransition } from '../components/common/PageTransition';

export default function ArtistsHubPage() {
  const [viewMode, setViewMode] = useState<'map' | 'list'>('map');
  const [activeArtist, setActiveArtist] = useState<string>('obsidian');

  const mockPins = [
    { id: 'obsidian', x: '40%', y: '50%', label: 'Obsidian Atelier' },
    { id: 'neon', x: '60%', y: '30%', label: 'Neon Ink Studio' },
    { id: 'void', x: '25%', y: '70%', label: 'Void Tattoo' },
    { id: 'chroma', x: '75%', y: '65%', label: 'Chroma Gallery' }
  ];

  return (
    <PageTransition>
      <div className="min-h-screen bg-zinc-950 flex flex-col overflow-hidden">
        <Navbar />

        {/* Main Content Area */}
        <main className="flex-1 relative flex overflow-hidden">

          {/* Simulated Map Background */}
          <div className="absolute inset-0 bg-zinc-950 bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:24px_24px]">

            {/* Mock Pins */}
            {mockPins.map(pin => (
              <div 
                key={pin.id}
                className="absolute flex flex-col items-center cursor-pointer transition-transform hover:scale-110"
                style={{ left: pin.x, top: pin.y, transform: 'translate(-50%, -50%)' }}
                onClick={() => setActiveArtist(pin.id)}
              >
                <div className={`w-4 h-4 rounded-full ${activeArtist === pin.id ? 'bg-violet-500 shadow-[0_0_15px_rgba(139,92,246,0.8)]' : 'bg-zinc-600'} transition-all`} />
                <span className={`mt-2 text-xs font-medium px-2 py-1 rounded-md backdrop-blur-sm ${activeArtist === pin.id ? 'text-white bg-zinc-900/80 border border-violet-500/30' : 'text-zinc-400 bg-zinc-900/50 border border-zinc-800'}`}>
                  {pin.label}
                </span>
              </div>
            ))}
          </div>

          {/* Floating Left Panel */}
          <div className="relative z-10 w-full md:w-[450px] h-full flex flex-col p-4 pointer-events-none">
            <div className="flex-1 w-full bg-zinc-900/80 backdrop-blur-md border border-zinc-800 rounded-2xl flex flex-col overflow-hidden pointer-events-auto shadow-2xl">

              {/* Search / Filter Bar */}
              <div className="p-4 border-b border-zinc-800 space-y-4">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500 w-4 h-4" />
                  <input 
                    type="text" 
                    placeholder="Location, style, or artist..." 
                    className="w-full bg-zinc-950 border border-zinc-800 rounded-xl py-2 pl-10 pr-4 text-sm text-white placeholder-zinc-500 focus:outline-none focus:border-violet-500 transition-colors"
                  />
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex gap-2">
                    <button className="px-3 py-1.5 rounded-lg text-xs font-medium bg-zinc-800 text-white hover:bg-zinc-700 transition-colors">
                      Radius: 10km
                    </button>
                    <button className="px-3 py-1.5 rounded-lg text-xs font-medium bg-zinc-800 text-white hover:bg-zinc-700 transition-colors">
                      Styles
                    </button>
                  </div>
                  <div className="flex p-1 bg-zinc-950 rounded-lg">
                    <button 
                      onClick={() => setViewMode('map')}
                      className={`p-1.5 rounded-md transition-colors ${viewMode === 'map' ? 'bg-zinc-800 text-white' : 'text-zinc-500'}`}
                    >
                      <MapIcon className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => setViewMode('list')}
                      className={`p-1.5 rounded-md transition-colors ${viewMode === 'list' ? 'bg-zinc-800 text-white' : 'text-zinc-500'}`}
                    >
                      <List className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>

              {/* List of Ateliers & Artistas */}
              <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
                <h2 className="text-sm font-semibold text-zinc-400 uppercase tracking-wider mb-2">Ateliers & Artistas</h2>

                {/* Expanded Card */}
                <div className="bg-zinc-950 border border-zinc-800 rounded-xl overflow-hidden shadow-lg">
                  <div className="relative h-40 w-full">
                    <img 
                      src="https://images.unsplash.com/photo-1598371839696-5c5bb00bdc28?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80" 
                      alt="Studio" 
                      className="w-full h-full object-cover"
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-zinc-950 via-zinc-950/40 to-transparent" />
                    <div className="absolute bottom-3 left-3 right-3 flex justify-between items-end">
                      <div>
                        <h3 className="text-lg font-bold text-white leading-tight">Obsidian Atelier & Flash Lab</h3>
                        <p className="text-xs text-zinc-400 mt-1 flex items-center gap-1">
                          <MapPin className="w-3 h-3 text-violet-500" />
                          Cyberpunk District, 2.4km
                        </p>
                      </div>
                      <div className="flex items-center gap-1 bg-zinc-900/80 px-2 py-1 rounded-md text-xs font-medium text-white backdrop-blur-sm">
                        <Star className="w-3 h-3 text-violet-500 fill-violet-500" />
                        4.9
                      </div>
                    </div>
                  </div>

                  <div className="p-4">
                    <p className="text-sm text-zinc-300 mb-4 line-clamp-2">
                      Resident Artist: <span className="text-white font-medium">Kaelen "Void" Silva</span>. 
                      Specializing in neo-tribal, cybersigilism, and dark geometry.
                    </p>

                    <div className="mb-4">
                      <div className="flex items-center justify-between mb-2">
                        <h4 className="text-xs font-medium text-zinc-400 uppercase tracking-wider">Flashes Disponibles Inmediatos</h4>
                        <span className="text-xs text-violet-500 hover:text-violet-400 cursor-pointer">Ver todos</span>
                      </div>

                      <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
                        {[
                          { img: "https://images.unsplash.com/photo-1611501275019-9b5cda994e8d?ixlib=rb-4.0.3&auto=format&fit=crop&w=300&q=80", price: "$120" },
                          { img: "https://images.unsplash.com/photo-1562962230-16e4623d36e6?ixlib=rb-4.0.3&auto=format&fit=crop&w=300&q=80", price: "$150" },
                          { img: "https://images.unsplash.com/photo-1621847468516-1ed15271c480?ixlib=rb-4.0.3&auto=format&fit=crop&w=300&q=80", price: "$90" },
                        ].map((flash, idx) => (
                          <div key={idx} className="relative w-20 h-20 rounded-lg overflow-hidden flex-shrink-0 group cursor-pointer border border-zinc-800">
                            <img src={flash.img} alt="Flash design" className="w-full h-full object-cover transition-transform group-hover:scale-110" />
                            <div className="absolute inset-x-0 bottom-0 bg-zinc-950/80 p-1 flex justify-center">
                              <span className="text-[10px] font-bold text-violet-400">{flash.price}</span>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>

                    <button className="w-full bg-violet-600 hover:bg-violet-500 text-white text-sm font-semibold py-2.5 rounded-xl transition-colors shadow-[0_0_15px_rgba(124,58,237,0.3)] hover:shadow-[0_0_20px_rgba(124,58,237,0.5)]">
                      Ver Flash Book & Reservar Cupo
                    </button>
                  </div>
                </div>

                {/* Collapsed Cards */}
                {[
                  { name: "Neon Ink Studio", style: "Color Realism", dist: "3.1km", img: "https://images.unsplash.com/photo-1598371839696-5c5bb00bdc28?ixlib=rb-4.0.3&auto=format&fit=crop&w=200&q=80" },
                  { name: "Void Tattoo", style: "Blackwork", dist: "5.0km", img: "https://images.unsplash.com/photo-1568515045052-f9a854d70bfd?ixlib=rb-4.0.3&auto=format&fit=crop&w=200&q=80" },
                  { name: "Chroma Gallery", style: "Watercolor", dist: "7.2km", img: "https://images.unsplash.com/photo-1611501275019-9b5cda994e8d?ixlib=rb-4.0.3&auto=format&fit=crop&w=200&q=80" }
                ].map((studio, idx) => (
                  <div key={idx} className="flex items-center gap-4 p-3 bg-zinc-950/50 border border-zinc-800/50 rounded-xl hover:bg-zinc-900 hover:border-zinc-700 transition-colors cursor-pointer group">
                    <div className="w-12 h-12 rounded-lg overflow-hidden flex-shrink-0">
                      <img src={studio.img} alt={studio.name} className="w-full h-full object-cover" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h4 className="text-sm font-medium text-white truncate">{studio.name}</h4>
                      <p className="text-xs text-zinc-500 flex items-center gap-1 mt-0.5">
                        <span className="text-zinc-400">{studio.style}</span> • {studio.dist}
                      </p>
                    </div>
                    <ChevronRight className="w-4 h-4 text-zinc-600 group-hover:text-violet-500 transition-colors" />
                  </div>
                ))}

              </div>
            </div>
          </div>
        </main>

        <style>{`
          .custom-scrollbar::-webkit-scrollbar {
            width: 4px;
          }
          .custom-scrollbar::-webkit-scrollbar-track {
            background: transparent;
          }
          .custom-scrollbar::-webkit-scrollbar-thumb {
            background: rgba(82, 82, 91, 0.5);
            border-radius: 9999px;
          }
          .custom-scrollbar::-webkit-scrollbar-thumb:hover {
            background: rgba(82, 82, 91, 0.8);
          }
          .no-scrollbar::-webkit-scrollbar {
            display: none;
          }
          .no-scrollbar {
            -ms-overflow-style: none;
            scrollbar-width: none;
          }
        `}</style>
      </div>
    </PageTransition>
  );
}
